    private static GodotObject Model(Control editor)=>editor.Get("model").AsGodotObject();private static GArray Actors(Control editor)=>Model(editor).Get("actors").AsGodotArray();private static GArray Clips(Control editor)=>Model(editor).Get("clips").AsGodotArray();private static string Number(double value)=>value.ToString("G",CultureInfo.InvariantCulture);
    public double temporal_sample_time(int frame,int samples,int fps,double shutter){if(samples<1||fps<1)return 0;double nominal=(double)(frame/samples)/fps;return samples>1?Math.Max(0,nominal+(((double)(frame%samples)+.5)/samples-.5)*shutter/fps):nominal;}
    public Camera3D? render_camera_for_time(Control editor,SubViewport viewport,Camera3D? fallback,double time){Camera3D? chosen=null;var actors=Actors(editor);var clips=Clips(editor);for(int i=0;i<actors.Count;i++){if(actors[i].As<Resource>().Get("type_id").AsString()!="camera_3d"||!_clips.contains_time(clips[i].As<Resource>(),time))continue;var runtime=editor.Call("_runtime_for_clip",clips[i].As<Resource>().Get("id")).As<Node>();if(runtime!=null&&runtime.Get("active").AsBool()&&runtime.Get("content").AsGodotObject() is Camera3D camera)chosen=camera;}chosen??=fallback;if(chosen!=null&&viewport.GetCamera3D()!=chosen)chosen.MakeCurrent();return chosen;}
    public GArray environment_targets(Control editor){var result=new GArray();var actors=Actors(editor);var clips=Clips(editor);double time=editor.Get("canvas").AsGodotObject().Get("playhead").AsDouble();for(int i=0;i<actors.Count;i++){var actor=actors[i].As<Resource>();var clip=clips[i].As<Resource>();if(actor.Get("type_id").AsString()!="environment_asset"||!_clips.contains_time(clip,time))continue;var runtime=editor.Call("_runtime_for_clip",clip.Get("id")).As<Node>();if(GodotObject.IsInstanceValid(runtime)&&runtime!.HasMethod("render_geometry_ready"))result.Add(new Settings{["runtime"]=runtime,["title"]=actor.Get("display_name")});}return result;}
    public Settings environment_status(GArray actors){bool ready=true;foreach(var item in actors){var entry=item.AsGodotDictionary();var runtime=entry["runtime"].AsGodotObject();if(!GodotObject.IsInstanceValid(runtime))continue;string error=runtime.HasMethod("render_geometry_error")?runtime.Call("render_geometry_error").AsString():"";if(error.Length>0)return new Settings{["ready"]=false,["error"]=entry["title"].AsString()+": "+error};if(!runtime.Call("render_geometry_ready").AsBool())ready=false;}return new Settings{["ready"]=ready,["error"]=""};}
    public GArray video_targets(Control editor,double time){var result=new GArray();var actors=Actors(editor);var clips=Clips(editor);for(int i=0;i<actors.Count;i++){var actor=actors[i].As<Resource>();if(actor.Get("type_id").AsString() is not ("video" or "video_2d"))continue;var clip=clips[i].As<Resource>();if(!_clips.contains_time(clip,time))continue;string path=_data.get_value(actor,new StringName("video"),"").AsString();if(path.Length>0)result.Add(new Settings{["path"]=path,["time"]=_clips.local_time(clip,time)});}return result;}
    public void cleanup_frames(string directory,int count){foreach(string name in DirAccess.GetFilesAt(directory))DirAccess.RemoveAbsolute(directory.PathJoin(name));DirAccess.RemoveAbsolute(directory);}
    public string audio_source(Variant value,string directory,int index)
    {
        bool Supported(string path)=>path.GetExtension().ToLowerInvariant() is "wav" or "mp3" or "ogg" or "flac";if(value.VariantType==Variant.Type.String&&Godot.FileAccess.FileExists(value.AsString())&&Supported(value.AsString()))return ProjectSettings.GlobalizePath(value.AsString());var stream=GD.Load<CSharpScript>("res://scripts/actors/core/ActorAudio.cs").Call("source",value).As<AudioStream>();if(stream==null)return "";if(stream.ResourcePath.Length>0&&Supported(stream.ResourcePath))return ProjectSettings.GlobalizePath(stream.ResourcePath);if(stream is AudioStreamWav wav){string path=directory.PathJoin("audio_"+index+".wav");return wav.SaveToWav(path)==Error.Ok?path:"";}if(stream.GetClass()=="AudioStreamMP3"){string path=directory.PathJoin("audio_"+index+".mp3");using var file=Godot.FileAccess.Open(path,Godot.FileAccess.ModeFlags.Write);if(file==null)return "";file.StoreBuffer(stream.Get("data").AsByteArray());return path;}return DecodeWav(stream,directory.PathJoin("audio_"+index+".wav"));
    }
    private static void Header(Godot.FileAccess file,int rate,uint bytes){file.Seek(0);file.StoreBuffer(Encoding.ASCII.GetBytes("RIFF"));file.Store32(bytes+36);file.StoreBuffer(Encoding.ASCII.GetBytes("WAVEfmt "));file.Store32(16);file.Store16(1);file.Store16(2);file.Store32((uint)rate);file.Store32((uint)rate*4);file.Store16(4);file.Store16(16);file.StoreBuffer(Encoding.ASCII.GetBytes("data"));file.Store32(bytes);}
    private static string DecodeWav(AudioStream stream,string path)
    {
        int rate=Math.Max(1,(int)AudioServer.GetMixRate());double requested=Math.Ceiling(stream.GetLength()*rate);if(!double.IsFinite(requested)||requested<=0||requested>(uint.MaxValue-36L)/4)return "";long frames=(long)requested,cursor=0;using var playback=stream.InstantiatePlayback();if(playback==null)return "";using(var file=Godot.FileAccess.Open(path,Godot.FileAccess.ModeFlags.Write)){if(file==null)return "";Header(file,rate,0);playback.Start(0);try{while(cursor<frames){var samples=playback.MixAudio(1,(int)Math.Min(4096,frames-cursor));if(samples.Length==0)break;var bytes=new byte[samples.Length*4];for(int i=0;i<samples.Length;i++){BinaryPrimitives.WriteInt16LittleEndian(bytes.AsSpan(i*4,2),(short)Math.Clamp(Mathf.RoundToInt(samples[i].X*32767),-32768,32767));BinaryPrimitives.WriteInt16LittleEndian(bytes.AsSpan(i*4+2,2),(short)Math.Clamp(Mathf.RoundToInt(samples[i].Y*32767),-32768,32767));}file.StoreBuffer(bytes);cursor+=samples.Length;}}finally{playback.Stop();}if(cursor>0)Header(file,rate,(uint)(cursor*4));}if(cursor==0){DirAccess.RemoveAbsolute(path);return "";}return path;
    }
    public string audio_filter(Resource actor,Resource clip,int index,double duration)
    {
        double Value(string key,double fallback){double value=_data.get_value(actor,new StringName(key),fallback).AsDouble();return double.IsFinite(value)?value:fallback;}double rawSpeed=clip.Get("playback_speed").AsDouble(),speed=double.IsFinite(rawSpeed)?Math.Max(.01,rawSpeed):1,pitch=Math.Max(.01,Value("pitch",1));var filters=new List<string>{"atrim=start="+Number(clip.Get("source_offset").AsDouble())+":duration="+Number(duration*speed),"asetpts=PTS-STARTPTS","aresample=44100","asetrate="+Mathf.RoundToInt((float)(44100*pitch)).ToString(CultureInfo.InvariantCulture),"aresample=44100"};double tempo=speed/pitch;if(!double.IsFinite(tempo))tempo=1;while(tempo>2){filters.Add("atempo=2.0");tempo/=2;}while(tempo<.5){filters.Add("atempo=0.5");tempo*=2;}filters.Add("atempo="+Number(tempo));filters.Add("volume="+Number(Mathf.DbToLinear((float)Value("volume_db",0))));filters.Add(_effects.pan_filter(Value("pan",0)));double fadeIn=Math.Min(duration,Math.Max(0,Value("fade_in",0))),fadeOut=Math.Min(duration,Math.Max(0,Value("fade_out",0)));if(fadeIn>0)filters.Add("afade=t=in:st=0:d="+Number(fadeIn));if(fadeOut>0)filters.Add("afade=t=out:st="+Number(Math.Max(0,duration-fadeOut))+":d="+Number(fadeOut));filters.Add("adelay="+Mathf.RoundToInt((float)(Math.Max(0,clip.Get("start_time").AsDouble())*1000)).ToString(CultureInfo.InvariantCulture)+":all=1");return "["+(index+1)+":a]"+string.Join(',',filters)+"[a"+index+"]";
    }
